    protected override Humidifier.DataZone.PolicyGrantTypes.PolicyGrantDetail Create()
    {
        var policyGrantDetailResult = CreatePolicyGrantDetail();
        factoryAction?.Invoke(policyGrantDetailResult);

        return policyGrantDetailResult;
    }

    private Humidifier.DataZone.PolicyGrantTypes.PolicyGrantDetail CreatePolicyGrantDetail()
    {
        var policyGrantDetailResult = new Humidifier.DataZone.PolicyGrantTypes.PolicyGrantDetail();

        return policyGrantDetailResult;
    }
    public override void CreateChildren(Humidifier.DataZone.PolicyGrantTypes.PolicyGrantDetail result)
    {
        base.CreateChildren(result);

        result.CreateGlossary ??= CreateGlossaryFactory?.Build();
        result.CreateAssetType ??= CreateAssetTypeFactory?.Build();
        result.CreateDomainUnit ??= CreateDomainUnitFactory?.Build();
        result.CreateProject ??= CreateProjectFactory?.Build();
        result.OverrideProjectOwners ??= OverrideProjectOwnersFactory?.Build();
        result.AddToProjectMemberPool ??= AddToProjectMemberPoolFactory?.Build();
        result.CreateProjectFromProjectProfile ??= CreateProjectFromProjectProfileFactory?.Build();
        result.CreateEnvironmentProfile ??= CreateEnvironmentProfileFactory?.Build();
        result.CreateFormType ??= CreateFormTypeFactory?.Build();
        result.OverrideDomainUnitOwners ??= OverrideDomainUnitOwnersFactory?.Build();
    }

